// Fence-aware Markdown section scanning, shared by the PR-body evidence readers — mt#3350.
//
// Extracted from `require-execution-evidence-before-merge.ts`, where these two helpers were
// module-private and served only that file's `extractExecutionEvidenceText`. mt#3350 adds a
// second reader (`success-criteria-coverage.ts`) that needs the SAME fence-awareness, and its
// Success Criterion 6 requires sharing this code rather than re-deriving it — a second
// hand-rolled fence scanner is exactly how the two readers would drift apart.
//
// The extraction is deliberately narrow: only the fence/heading primitives move.
// `extractExecutionEvidenceText` stays in the evidence hook, because its heading vocabulary
// (`Execution evidence:`, plus mt#3316's acceptance-tests widening) belongs to that gate.
//
// Dependency-free per `.minsky/hooks/SPEC.md`'s invariant — no imports at all.
//
// @see mt#3350 — the task that extracted this
// @see .minsky/hooks/require-execution-evidence-before-merge.ts — original home, still a consumer
// @see .minsky/hooks/success-criteria-coverage.ts — the second consumer this extraction exists for

/**
 * Matches a fenced-code-block delimiter line (opening or closing): backtick OR tilde
 * fence, 3+ markers, up to 3 leading spaces per CommonMark. Mirrors the fence-marker
 * regex in `elision.ts`'s `elideQuotedContexts` — kept as a per-line predicate rather
 * than a reuse of that module's whole-string blank-and-replace transform, which would
 * incorrectly blank the real pasted test-run output an `Execution evidence:` block
 * usually contains.
 */
const FENCE_DELIMITER_PATTERN = /^ {0,3}(`{3,}|~{3,})/;

/** Matches a real Markdown heading line: up to 3 leading spaces, 1-6 `#`, then whitespace. */
const HEADING_LINE_PATTERN = /^ {0,3}#{1,6}\s/;

/**
 * Computes, for each line index in `lines`, whether that line sits INSIDE a fenced
 * code block — between an opening delimiter and its matching close. Delimiter lines
 * themselves are never marked fence-internal (irrelevant either way: a fence marker
 * never matches a heading pattern), only the lines BETWEEN them are. Single forward
 * pass over the whole document, O(n) — correct as long as fences are balanced, which a
 * well-formed PR body's Markdown always is.
 *
 * Why this matters (PR #2410 R1 BLOCKING #1, mt#3316): a PR body legitimately pastes
 * example Markdown or terminal output inside ``` fences, and a heading-looking line in
 * there (an illustrative `### Acceptance tests` snippet, or a test-failure message
 * starting with `# `) must not be misread as a real section boundary — it would either
 * wrongly widen a scan into unrelated pasted content, or wrongly truncate a real
 * evidence block early.
 */
export function computeFenceInternalLines(lines: string[]): boolean[] {
  const result: boolean[] = new Array(lines.length).fill(false);
  let inFence = false;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line !== undefined && FENCE_DELIMITER_PATTERN.test(line)) {
      inFence = !inFence;
      continue;
    }
    result[i] = inFence;
  }
  return result;
}

/**
 * Collects the content of every section in `lines` whose heading line matches
 * `isHeadingLine`, from just after the heading up to (not including) the next Markdown
 * heading of any level, or end-of-string. Extracted so multiple scan passes share ONE
 * boundary implementation. `fenceInternal[i]` (from {@link computeFenceInternalLines})
 * gates BOTH the heading-candidacy check and the next-heading stop condition, so a
 * heading-like line inside a fence is neither treated as a new section start nor as the
 * boundary that ends collection.
 */
export function collectHeadingSections(
  lines: string[],
  fenceInternal: boolean[],
  isHeadingLine: (line: string) => boolean
): string[] {
  const collected: string[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line === undefined || fenceInternal[i] || !isHeadingLine(line)) continue;
    for (let j = i + 1; j < lines.length; j++) {
      const nextLine = lines[j];
      if (nextLine === undefined) break;
      if (!fenceInternal[j] && HEADING_LINE_PATTERN.test(nextLine)) break;
      collected.push(nextLine);
    }
  }
  return collected;
}

/** True when `line` is a real Markdown heading (the same predicate section scans stop at). */
export function isMarkdownHeading(line: string): boolean {
  return HEADING_LINE_PATTERN.test(line);
}
